import { useEffect, useId, useMemo, useRef, useState } from 'react';
import { api } from '../infrastructure/api.js';
import { configuredPizzaSizes, formatMoney, formatTicketDetails, normalizeProductHierarchy, pizzaPriceForSubcategory, priceForProduct, productCategories, productParentCategory, productSubcategory, selectableProducts } from '../domain/menu-model.js';

const labels = { inicio: 'Resumen', caja: 'Caja', pedidos: 'Pedidos', cocina: 'Comandas', carta: 'Mi carta', ajustes: 'Ajustes', nuevo: 'Nuevo pedido', detalle: 'Detalle del pedido' };
const categories = { pizzas: 'Pizzas', pizzas_clasicas: 'Clásicas', pizzas_especialidades: 'Especialidades', pizzas_gourmet: 'Gourmet', snacks: 'Snacks', snacks_extras: 'Snacks y extras', extras: 'Extras', ensaladas: 'Ensaladas', pastas: 'Pastas', alitas_boneless: 'Alitas y boneless', hamburguesas: 'Hamburguesas', bebidas: 'Bebidas' };
const stations = ['Pizzas', 'Platillos', 'Bebidas'];
const emptyDraft = () => ({ type: 'mesa', table: '', guests: 2, source: 'telefono', customerName: '', phone: '', address: '', orderNote: '', items: [] });
const money = (store, value) => formatMoney(value, store.settings?.currency || 'MXN');
const isOpen = order => !['cerrado', 'cancelado', 'cerrado_turno'].includes(order.status);
const hasPendingCommand = order => isOpen(order) && order.tickets?.some(ticket => ticket.status !== 'listo');
const subtotal = order => (order.items || []).reduce((total, item) => total + Number(item.unitPrice || 0) * Number(item.quantity || 1), 0);
const stationFor = product => product.kind === 'pizza' || product.kind === 'pizza-menu' || product.category?.startsWith('pizzas') ? 'Pizzas' : product.category === 'bebidas' || product.kind === 'beverage-menu' ? 'Bebidas' : 'Platillos';
const phone = value => { const d = String(value || '').replace(/\D/g, '').slice(0, 10); return d.length > 6 ? `${d.slice(0, 3)}-${d.slice(3, 6)}-${d.slice(6)}` : d.length > 3 ? `${d.slice(0, 3)}-${d.slice(3)}` : d; };
const typeLabel = order => order.type === 'mesa' ? 'En mesa' : order.type === 'domicilio' ? 'Domicilio' : 'Recoger aquí';
const comboOpenEvent = 'pizzas:combo-open';
const orderStatus = status => ({
  nuevo: { key:'abierto', label:'Abierto' }, abierto: { key:'abierto', label:'Abierto' },
  pendiente: { key:'pendiente', label:'Pendiente' }, preparando: { key:'preparando', label:'En preparación' },
  listo: { key:'listo', label:'Listo' }, en_ruta: { key:'en-ruta', label:'En reparto' },
  entregado: { key:'entregado', label:'Entregado' }, cerrado: { key:'cerrado', label:'Cerrado' },
  cerrado_turno: { key:'cerrado-turno', label:'Cerrado al corte' },
  cancelado: { key:'cancelado', label:'Cancelado' }
}[status] || { key:'abierto', label:'Abierto' });
const dishIcon = product => ({ hamburguesas: 'burger', bebidas: 'glass-cocktail', ensaladas: 'salad', alitas_boneless: 'meat', extras: 'cheese', snacks: 'bowl-spoon', snacks_extras: 'bowl-spoon', pastas: 'bowl-spoon' }[product.category] || (product.kind?.includes('pizza') ? 'pizza' : 'bowl-spoon'));
function printTicket(store, order, station = null, receipt = false) {
  const items = station ? order.items.filter(item => item.station === station) : order.items;
  const popup = window.open('', '_blank', 'width=400,height=680'); if (!popup) return false;
  const safe = value => String(value || '').replace(/[&<>"']/g, character => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' })[character]);
  const ticketDate = new Date(order.createdAt || Date.now());
  const dateLabel = new Intl.DateTimeFormat('es-MX', { dateStyle:'short' }).format(ticketDate);
  const timeLabel = new Intl.DateTimeFormat('es-MX', { timeStyle:'short' }).format(ticketDate);
  const branchPhone = safe(store.settings.phone || '413-162-86-05');
  const title = receipt ? `CUENTA · Venta ${order.number}` : station?.toUpperCase();
  const rows = items.map(item => `<article><b>${safe(item.quantity)} × ${safe(String(item.name || '').toLocaleUpperCase('es-MX'))}</b><p>${safe(formatTicketDetails(item))}</p>${item.note ? `<p>Nota: ${safe(item.note)}</p>` : ''}</article>`).join('');
  const paymentStatus = order.payment?.method ? `<p>Pago: ${safe(order.payment.method)}</p>` : order.type === 'domicilio' ? '<p><b>PAGO PENDIENTE CON EL REPARTIDOR</b></p>' : '';
  const totals = receipt ? `<hr><p>Subtotal: ${money(store, subtotal(order))}</p>${order.payment?.cardFee ? `<p>Comisión: ${money(store,order.payment.cardFee)}</p>` : ''}${order.payment?.tip ? `<p>Propina: ${money(store,order.payment.tip)}</p>` : ''}<h2>TOTAL ${money(store,order.payment?.total || subtotal(order))}</h2>${paymentStatus}` : '';
  const deliveryData = receipt && order.type === 'domicilio' ? `<div>${safe(order.customerName || 'Cliente')}</div><div>+52 ${safe(order.phone)}</div><div>${safe(order.address)}</div>` : '';
  const receiptDate = receipt ? `<div class="ticket-date"><div>Fecha: ${safe(dateLabel)}</div><div>Hora: ${safe(timeLabel)}</div></div>` : '';
  const branchContact = receipt ? `<div class="branch-contact">${branchPhone}</div>` : '';
  const nonInvoiceNotice = receipt && ['Tarjeta', 'Transferencia'].includes(order.payment?.method) ? '<div class="non-invoice-notice">DOCUMENTO NO VALIDO COMO FACTURA</div>' : '';
  const paperWidth = ['58mm','80mm'].includes(store.settings.paperWidth) ? store.settings.paperWidth : '58mm';
  popup.opener = null;
  popup.onload = () => { popup.focus(); popup.print(); popup.onafterprint = () => popup.close(); };
  popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'"><title>${safe(title)}</title><style>@page{size:${paperWidth} auto;margin:3mm}body{font:12px Arial;margin:auto;max-width:72mm;color:#111}header{text-align:center;border-bottom:1px dashed #333;padding-bottom:6px}article{padding:7px 0;border-bottom:1px dotted #aaa}p{margin:3px 0}h2{font-size:16px}.ticket-date{margin:5px 0}.ticket-date div{margin:2px 0}footer{margin-top:8px}.branch-contact{text-align:center;margin-top:12px;padding-top:7px;border-top:1px dashed #333;font-weight:bold}.non-invoice-notice{text-align:center;margin-top:8px;padding-top:7px;border-top:1px dotted #777;font-size:10px;font-weight:bold}</style></head><body><header><strong>${safe(store.settings.restaurantName || 'Pizzas a la Leña')}</strong><h2>${safe(title)}</h2>${receipt ? `<b>Venta #${safe(order.number)}</b>` : `<div>${safe(new Date(order.createdAt).toLocaleString('es-MX'))}</div>`}${receiptDate}<div>${order.type === 'mesa' ? `MESA ${safe(order.table)}` : safe(typeLabel(order))}</div>${deliveryData}</header>${rows}<footer>${totals}${branchContact}${nonInvoiceNotice}</footer></body></html>`); popup.document.close();
  return true;
}

export function Combo({ value, onChange, options, label = 'Seleccionar' }) {
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const openRef = useRef(false);
  const rootRef = useRef(null);
  const comboId = useId();
  const listId = `combo-list-${comboId.replace(/:/g, '')}`;
  useEffect(() => {
    const closeOtherCombo = event => {
      if (event.detail !== rootRef.current) {
        openRef.current = false;
        setOpen(false);
      }
    };
    const closeOutside = event => {
      if (!rootRef.current?.contains(event.target)) {
        openRef.current = false;
        setOpen(false);
      }
    };
    const closeOnEscape = event => {
      if (event.key !== 'Escape' || !openRef.current) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      openRef.current = false;
      setOpen(false);
    };
    document.addEventListener(comboOpenEvent, closeOtherCombo);
    document.addEventListener('pointerdown', closeOutside, true);
    document.addEventListener('keydown', closeOnEscape, true);
    return () => {
      document.removeEventListener(comboOpenEvent, closeOtherCombo);
      document.removeEventListener('pointerdown', closeOutside, true);
      document.removeEventListener('keydown', closeOnEscape, true);
    };
  }, []);
  const uniqueOptions = options.filter((option, index, values) => option.group || values.findIndex(candidate => !candidate.group && String(candidate.value) === String(option.value)) === index);
  const selected = uniqueOptions.find(option => String(option.value) === String(value));
  const selectableOptions = uniqueOptions.filter(option => !option.group);
  const choose = option => { onChange(option.value); openRef.current = false; setOpen(false); setActiveIndex(-1); };
  const toggle = () => {
    if (open) {
      openRef.current = false;
      return setOpen(false);
    }
    document.dispatchEvent(new CustomEvent(comboOpenEvent, { detail: rootRef.current }));
    openRef.current = true;
    setOpen(true);
    setActiveIndex(Math.max(0, selectableOptions.findIndex(option => String(option.value) === String(value))));
  };
  const onKeyDown = event => {
    if (event.key === 'Escape' && open) { event.preventDefault(); openRef.current=false; setOpen(false); return; }
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      if (!open) return toggle();
      if (selectableOptions[activeIndex]) choose(selectableOptions[activeIndex]);
      return;
    }
    if (!['ArrowDown','ArrowUp','Home','End'].includes(event.key)) return;
    event.preventDefault();
    if (!open) { toggle(); return; }
    setActiveIndex(current => event.key === 'Home' ? 0 : event.key === 'End' ? selectableOptions.length - 1 : event.key === 'ArrowDown' ? Math.min(selectableOptions.length - 1, current + 1) : Math.max(0, current - 1));
  };
  return <div ref={rootRef} className={`system-combo ${open ? 'is-open' : ''}`}>
    <button type="button" className="system-combo-trigger" aria-haspopup="listbox" aria-controls={listId} aria-expanded={open} onClick={toggle} onKeyDown={onKeyDown}><span className="system-combo-label">{selected?.label || label}</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m19 9-7 7-7-7" /></svg></button>
    <ul id={listId} className="system-combo-list" role="listbox">{uniqueOptions.map(option => { const optionIndex=selectableOptions.indexOf(option); return option.group ? <li className="system-combo-group" key={`group-${option.label}`}>{option.label}</li> : <li key={option.value}><button type="button" role="option" aria-selected={String(value) === String(option.value)} className={`system-combo-option ${String(value) === String(option.value) ? 'is-selected' : ''} ${activeIndex === optionIndex ? 'is-keyboard-active' : ''}`} onMouseEnter={()=>setActiveIndex(optionIndex)} onClick={() => choose(option)}>{option.label}</button></li>; })}</ul>
  </div>;
}

function PizzaScene({ config }) {
  const ref = useRef(null);
  useEffect(() => {
    if (!ref.current) return undefined;
    const left = config.options.find(item => item.id === config.left) || config.options[0];
    const right = config.options.find(item => item.id === config.right) || left;
    let disposed = false; let module;
    import('../ui/pizza-3d.js').then(loaded => { if (!disposed && ref.current) { module = loaded; loaded.animatePizza(ref.current, { mode: config.mode, activeHalf: config.activeHalf, leftName: left?.name, rightName: right?.name }); } });
    return () => { disposed = true; module?.disposePizzaAnimations(); };
  }, [config]);
  return <div className="three-pizza-scene" ref={ref} role="img" aria-label="Vista configurada de la pizza" />;
}

function Modal({ children, onClose, title }) {
  const cardRef = useRef(null);
  useEffect(() => {
    const previousFocus = document.activeElement;
    const focusable = () => [...(cardRef.current?.querySelectorAll('button:not([disabled]), input:not([disabled]), textarea:not([disabled]), [href], [tabindex]:not([tabindex="-1"])') || [])];
    focusable()[0]?.focus();
    const handleKeys = event => {
      if (event.key === 'Escape') return onClose();
      if (event.key !== 'Tab') return;
      const elements=focusable(); if (!elements.length) return;
      const first=elements[0], last=elements[elements.length-1];
      if (event.shiftKey && document.activeElement===first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement===last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', handleKeys);
    return () => { document.removeEventListener('keydown', handleKeys); previousFocus?.focus?.(); };
  }, [onClose]);
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) onClose(); }}><section ref={cardRef} className="modal-card" role="dialog" aria-modal="true" aria-label={title}><button type="button" className="modal-close icon-button" onClick={onClose} aria-label="Cerrar">×</button>{children}</section></div>;
}

function Auth({ configured, onLogin, sessionMessage = '' }) {
  const [error, setError] = useState(sessionMessage);
  const submit = async event => {
    event.preventDefault(); const data = new FormData(event.currentTarget); const password = String(data.get('password') || '');
    try {
      if (!configured && password !== String(data.get('confirmPassword') || '')) throw new Error('Las contraseñas no coinciden.');
      if (configured) await api.login({ username: data.get('username'), password }); else await api.setupAuth({ username: 'pizzas', password });
      await onLogin();
    } catch (exception) { setError(exception.message); }
  };
  return <main className="auth-layout"><section className="auth-card"><div className="auth-brand"><span className="brand-mark"><span /><span /><span /></span><span><strong>Pizzas</strong><small>a la leña</small></span></div><span className="eyebrow">{configured ? 'ACCESO DEL RESTAURANTE' : 'CONFIGURACIÓN INICIAL'}</span><h1>{configured ? 'Bienvenido de nuevo' : 'Crea tu contraseña'}</h1><p>{configured ? 'Ingresa con la cuenta del restaurante para abrir el área de operación.' : 'El usuario inicial es pizzas y este acceso se guarda en este equipo.'}</p><form className="auth-form" onSubmit={submit}>{configured ? <label>Usuario<input name="username" defaultValue="pizzas" required /></label> : <label className="auth-fixed-user">Usuario <strong>pizzas</strong></label>}<label>Contraseña<input name="password" type="password" minLength="10" maxLength="128" required autoFocus /></label>{!configured && <><label>Confirmar contraseña<input name="confirmPassword" type="password" minLength="10" maxLength="128" required /></label><small className="password-help">Mínimo 10 caracteres, con mayúscula, minúscula y número.</small></>}{error && <div className="auth-error">{error}</div>}<button className="button button-primary button-full">{configured ? 'Entrar al sistema' : 'Guardar acceso y continuar'} <span>→</span></button></form></section><aside className="auth-side-art"><img src="/assets/portada-menu.jpeg" alt="Horno de leña" /><div><span className="eyebrow">PIZZAS A LA LEÑA</span><h2>La operación,<br />lista para el servicio.</h2></div></aside></main>;
}

export function App() {
  const [store, setStore] = useState({ settings: {}, catalog: [], orders: [], cashSessions: [], users: [] });
  const [configured, setConfigured] = useState(true); const [ready, setReady] = useState(false); const [page, setPage] = useState('inicio');
  const [draft, setDraft] = useState(null); const [modal, setModal] = useState(null); const [selected, setSelected] = useState(null); const [notice, setNotice] = useState(null); const [sessionMessage, setSessionMessage] = useState('');
  const refresh = async () => { const data = await api.bootstrap(); setStore(data); setReady(true); return data; };
  useEffect(() => { api.authStatus().then(status => { setConfigured(status.configured); if (status.configured) return refresh(); setStore(current => ({ ...current, currentUser:null })); setReady(true); return null; }).catch(() => setReady(true)); }, []);
  useEffect(() => { const expired = () => { setStore({ settings:{}, catalog:[], orders:[], cashSessions:[], users:[] }); setDraft(null); setModal(null); setSelected(null); setPage('inicio'); setSessionMessage('Tu sesión terminó por seguridad. Ingresa nuevamente.'); }; window.addEventListener('pizzas:session-expired', expired); return () => window.removeEventListener('pizzas:session-expired', expired); }, []);
  useEffect(() => { const timeout = notice ? setTimeout(() => setNotice(null), 3200) : null; return () => clearTimeout(timeout); }, [notice]);
  const toast = (text, tone = 'success') => setNotice({ text, tone });
  const sessionOrders = store.activeCashSession ? store.orders.filter(order => order.cashSessionId === store.activeCashSession.id) : [];
  const navigate = next => { setPage(next); if (next !== 'nuevo') setDraft(current => current?.items?.length ? current : null); };
  if (!ready) return <div className="loading-card">Preparando tu área de pedidos…</div>;
  if (!store.currentUser) return <Auth configured={configured} sessionMessage={sessionMessage} onLogin={async () => { setConfigured(true); setSessionMessage(''); await refresh(); }} />;
  if (store.closedCashSummary) return <CashCloseReport store={store} session={store.closedCashSummary} onNewCash={async () => { await api.acknowledgeCashClose(); await refresh(); }} onLogout={async () => { await api.logout(); setStore({ settings:{}, catalog:[], orders:[], cashSessions:[] }); }} />;
  if (!store.activeCashSession) return <CashGate store={store} onOpen={async data => { await api.openCash(data); await refresh(); toast('Caja abierta.'); }} onLogout={async () => { await api.logout(); setStore({ settings:{}, catalog:[], orders:[], cashSessions:[], users:[] }); }} />;
  const openOrder = order => { setSelected(order.id); setPage('detalle'); };
  const content = page === 'inicio' ? <Dashboard store={store} orders={sessionOrders} onNew={() => { setDraft(emptyDraft()); navigate('nuevo'); }} onOrders={() => navigate('pedidos')} onOpen={openOrder} />
    : page === 'caja' ? <Cash store={store} onClose={async countedCash => { await api.closeCash({ countedCash }); await refresh(); }} />
      : page === 'pedidos' ? <Orders store={store} orders={store.orders} onNew={() => { setDraft(emptyDraft()); navigate('nuevo'); }} onOpen={openOrder} />
        : page === 'cocina' ? <Kitchen store={store} orders={sessionOrders} onRefresh={refresh} onOpen={openOrder} toast={toast} />
          : page === 'carta' ? <Catalog store={store} toast={toast} onRefresh={refresh} onModal={setModal} />
            : page === 'ajustes' ? <Settings store={store} onRefresh={refresh} toast={toast} />
              : page === 'nuevo' ? <NewOrder store={store} draft={draft || emptyDraft()} setDraft={setDraft} onModal={setModal} onOpenOrder={order => { setSelected(order.id); setDraft(null); setPage('detalle'); }} onBackToOrder={() => { setDraft(null); setPage('detalle'); }} onSend={async order => { const additions = Boolean(order.existingOrderId); const saved = additions ? await api.addOrderItems(order.existingOrderId, order.items) : await api.createOrder(order); stations.filter(station => order.items.some(item => item.station === station)).forEach(station => printTicket(store, additions ? { ...saved, items: order.items } : saved, station)); await refresh(); setSelected(saved.id); setDraft(null); setPage('detalle'); toast(additions ? 'Nuevas partidas enviadas a cocina.' : `Pedido #${String(saved.number).padStart(3, '0')} enviado a cocina`); }} />
                : <OrderDetail store={store} order={store.orders.find(order => order.id === selected)} onBack={() => navigate('pedidos')} onRefresh={refresh} onModal={setModal} toast={toast} onAdd={order => { setDraft({ type:order.type,table:order.table,guests:order.guests,source:order.source,customerName:order.customerName,phone:order.phone,address:order.address,orderNote:'',items:[],existingOrderId:order.id }); setPage('nuevo'); }} />;
  return <div className="app-shell"><Sidebar page={page} orders={sessionOrders} onNavigate={navigate} /><div className="app-frame"><header className="topbar"><div className="breadcrumb"><span>Operación</span><span className="crumb-sep">/</span><strong>{labels[page]}</strong></div><div className="topbar-actions"><span className="today-label">{new Intl.DateTimeFormat('es-MX', { dateStyle: 'full' }).format(new Date())}</span><button className="avatar-button" onClick={() => navigate('ajustes')}>PX</button><button className="logout-button" onClick={async () => { try { await api.logout(); setStore({ settings: {}, catalog: [], orders: [] }); } catch (error) { toast(error.message, 'error'); } }}>Salir</button></div></header><main id="main-content" className="react-page-transition" key={page}>{content}</main></div>{modal && <ProductModal store={store} modal={modal} setModal={setModal} onRefresh={refresh} toast={toast} addItem={item => setDraft(current => ({ ...(current || emptyDraft()), items: [...(current?.items || []), { ...item, lineId: crypto.randomUUID() }] }))} />} {notice && <div className="toast-region" aria-live="polite"><div className={`toast toast-${notice.tone}`}><span>{notice.tone === 'error' ? '!' : '✓'}</span>{notice.text}</div></div>}</div>;
}

function Sidebar({ page, orders, onNavigate }) { const pendingCommands = orders.filter(hasPendingCommand).length; return <aside className="sidebar"><button type="button" className="brand" onClick={() => onNavigate('inicio')}><span className="brand-mark"><span /><span /><span /></span><span><strong>Pizzas</strong><small>a la leña</small></span></button><div className="sidebar-caption">RESTAURANTE</div><nav className="primary-nav">{[['inicio','⌂'],['caja','$'],['pedidos','▤'],['cocina','♨'],['carta','▦']].map(([key, icon]) => <button key={key} className={`nav-link ${page === key ? 'is-active' : ''}`} onClick={() => onNavigate(key)}><span className="nav-icon">{icon}</span>{labels[key]}{key === 'pedidos' && <span className="nav-count">{orders.filter(isOpen).length}</span>}{key === 'cocina' && <span className="nav-count" aria-label={`${pendingCommands} comandas pendientes`}>{pendingCommands}</span>}</button>)}</nav><div className="sidebar-bottom"><button className={`nav-link ${page === 'ajustes' ? 'is-active' : ''}`} onClick={() => onNavigate('ajustes')}><span className="nav-icon">⚙</span>Ajustes</button><div className="local-note"><span className="local-dot" /><span><strong>Equipo local</strong><small>Datos guardados aquí</small></span></div></div></aside>; }

function CashGate({ store, onOpen, onLogout }) {
  const [error, setError] = useState(''); const [working, setWorking] = useState('');
  const logout = async () => { try { setError(''); setWorking('logout'); await onLogout(); } catch (exception) { setError(exception.message); setWorking(''); } };
  return <main className="auth-layout cash-gate"><section className="auth-card"><div className="auth-brand"><span className="brand-mark"><span /><span /><span /></span><span><strong>Pizzas</strong><small>a la leña</small></span></div><span className="eyebrow">INICIO DEL TURNO · {store.currentUser.role}</span><h1>Apertura de caja</h1><p>Registra el fondo inicial para comenzar un nuevo día de operación.</p><form className="auth-form" onSubmit={async event => { event.preventDefault(); try { setError(''); setWorking('open'); const form = new FormData(event.currentTarget); await onOpen({ openingCash: Number(form.get('openingCash')), note: String(form.get('note') || '') }); } catch (exception) { setError(exception.message); setWorking(''); } }}><label>Fondo inicial<input name="openingCash" type="number" min="0" defaultValue="0" required disabled={Boolean(working)} /></label><label>Nota del turno<input name="note" maxLength="240" disabled={Boolean(working)} /></label>{error && <div className="auth-error" role="alert">{error}</div>}<button className="button button-primary button-full" disabled={Boolean(working)}>{working === 'open' ? 'Abriendo caja…' : 'Abrir caja y comenzar →'}</button><div className="cash-gate-logout"><span>Usuario actual: <strong>{store.currentUser.username}</strong></span><button type="button" className="button button-secondary button-full" disabled={Boolean(working)} onClick={logout}>{working === 'logout' ? 'Cerrando sesión…' : '← Cerrar sesión y volver al acceso'}</button></div></form></section><aside className="auth-side-art"><img src="/assets/portada-menu.jpeg" alt="Horno de leña" /></aside></main>;
}

function CashCloseReport({ store, session, onNewCash, onLogout }) {
  const [working, setWorking] = useState(''); const [error, setError] = useState('');
  const report = session.report || {}; const difference = Number(report.difference || 0);
  const differenceState = difference === 0 ? { label:'Caja exacta', className:'exacta' } : difference > 0 ? { label:'Sobrante', className:'sobrante' } : { label:'Faltante', className:'faltante' };
  const orders = store.orders.filter(order => order.cashSessionId === session.id).sort((left,right) => new Date(left.createdAt) - new Date(right.createdAt));
  const totalCollected = Number(report.totalSales ?? Object.values(report.methodTotals || {}).reduce((sum, value) => sum + Number(value || 0), 0));
  const cashSales = Number(report.cashSales ?? report.methodTotals?.Efectivo ?? 0);
  const expectedTurnTotal = Number(report.expectedTurnTotal ?? Number(session.openingCash || 0) + totalCollected);
  const tipTotals = report.tipTotals || Object.fromEntries(['Tarjeta','Transferencia'].map(method => [method, orders.filter(order => order.paid && order.payment?.method === method).reduce((sum, order) => sum + Number(order.payment?.tip || 0), 0)]));
  const perform = async (action, callback) => { try { setWorking(action); setError(''); await callback(); } catch (exception) { setError(exception.message); setWorking(''); } };
  return <main className="cash-close-report-page"><header className="cash-report-topbar"><div className="auth-brand"><span className="brand-mark"><span /><span /><span /></span><span><strong>Pizzas</strong><small>a la leña</small></span></div><div><span>Reporte privado</span><strong>{store.currentUser.username}</strong></div></header><div className="cash-report-content"><section className="cash-report-heading"><div><span className="eyebrow">CORTE DE CAJA COMPLETADO</span><h1>Resumen del turno</h1><p>{new Intl.DateTimeFormat('es-MX',{dateStyle:'full'}).format(new Date(session.closedAt))} · Cerrado por {session.closedBy || store.currentUser.username}</p></div><span className={`cash-difference-badge is-${differenceState.className}`}>{differenceState.label}</span></section><section className="cash-close-metrics"><article><span>Fondo para cambio</span><strong>{money(store,session.openingCash)}</strong></article><article><span>Ventas cobradas</span><strong>{money(store,totalCollected)}</strong></article><article className="cash-total-turn"><span>Total esperado del turno</span><strong>{money(store,expectedTurnTotal)}</strong><small>Cambio + todas las ventas</small></article><article><span>Pedidos del turno</span><strong>{orders.length}</strong></article><article><span>Pedidos cobrados</span><strong>{report.paidOrders || 0}</strong></article></section><div className="cash-report-grid"><section className="panel cash-breakdown-panel"><div className="section-heading"><div><span className="eyebrow">DESGLOSE</span><h2>Movimiento registrado</h2></div></div><div className="cash-payment-breakdown"><article><span>EFECTIVO</span><strong>{money(store,report.methodTotals?.Efectivo)}</strong><small>Sin propinas registradas</small></article><article><span>TARJETA</span><strong>{money(store,report.methodTotals?.Tarjeta)}</strong><div><small>Comisión terminal</small><b>{money(store,report.cardFees)}</b></div><div><small>Propinas con tarjeta</small><b>{money(store,tipTotals.Tarjeta)}</b></div></article><article><span>TRANSFERENCIA</span><strong>{money(store,report.methodTotals?.Transferencia)}</strong><div><small>Propinas por transferencia</small><b>{money(store,tipTotals.Transferencia)}</b></div></article></div><div className="cash-report-lines cash-operational-lines"><div><span>Pedidos cancelados</span><strong>{report.cancelledOrders || 0}</strong></div><div><span>Pedidos cerrados al corte</span><strong>{report.autoClosedOrders || 0}</strong></div><div><span>Pedidos que quedaron abiertos</span><strong>{report.openOrders || 0}</strong></div></div></section><section className={`panel cash-balance-panel is-${differenceState.className}`}><span className="eyebrow">ARQUEO FINAL</span><div><span>Efectivo esperado en caja</span><strong>{money(store,report.expectedCash)}</strong></div><small className="cash-balance-formula">{money(store,session.openingCash)} de cambio + {money(store,cashSales)} de ventas en efectivo</small><div><span>Efectivo contado</span><strong>{money(store,report.countedCash)}</strong></div><hr/><div className="cash-final-difference"><span>{differenceState.label}</span><strong>{money(store,Math.abs(difference))}</strong></div><p>{difference === 0 ? 'El efectivo contado coincide con el sistema.' : difference > 0 ? 'Se registró más efectivo del esperado.' : 'Se registró menos efectivo del esperado.'}</p></section></div><section className="panel cash-orders-panel"><div className="section-heading"><div><span className="eyebrow">PEDIDOS DEL DÍA</span><h2>Operaciones del turno</h2></div><span>{orders.length} pedidos</span></div><div className="cash-orders-table"><div className="cash-orders-head"><span>Folio</span><span>Hora</span><span>Servicio</span><span>Estado</span><span>Total</span></div>{orders.map(order => <div className="cash-order-row" key={order.id}><strong>#{String(order.number).padStart(3,'0')}</strong><span>{new Intl.DateTimeFormat('es-MX',{hour:'2-digit',minute:'2-digit'}).format(new Date(order.createdAt))}</span><span>{typeLabel(order)}</span><span className={`status-pill status-${orderStatus(order.status).key}`}>{orderStatus(order.status).label}</span><strong>{money(store,order.payment?.total || subtotal(order))}</strong></div>)}{orders.length === 0 && <div className="catalog-empty">No se registraron pedidos durante este turno.</div>}</div></section>{error && <div className="auth-error" role="alert">{error}</div>}<section className="cash-report-actions"><div><strong>El reporte queda guardado localmente.</strong><span>Descargar o imprimir el PDF es opcional.</span></div><a className="button button-secondary" href={`/api/cash-sessions/${session.id}/report.pdf`} download>⇩ Descargar PDF</a><button className="button button-secondary" disabled={Boolean(working)} onClick={() => perform('logout',onLogout)}>{working === 'logout' ? 'Cerrando…' : 'Cerrar sesión'}</button><button className="button button-primary" disabled={Boolean(working)} onClick={() => perform('new',onNewCash)}>{working === 'new' ? 'Preparando…' : 'Iniciar nueva caja →'}</button></section></div></main>;
}

function Dashboard({ store, orders, onNew, onOrders, onOpen }) { const active = orders.filter(isOpen), sales = orders.filter(order => order.status !== 'cancelado').reduce((sum, order) => sum + (order.payment?.total || subtotal(order)), 0); return <><section className="welcome-panel"><div className="welcome-copy"><span className="eyebrow"><span className="live-dot" /> SISTEMA LOCAL · TURNO ACTIVO</span><h1>El horno está encendido.</h1><p>Toma pedidos, manda cada platillo a su estación y sigue el avance desde aquí.</p><button className="button button-primary" onClick={onNew}>＋ Nuevo pedido</button></div><img src="/assets/portada-menu.jpeg" className="welcome-art" alt="Horno de leña" /></section><section className="metric-grid"><Metric icon="▤" label="Pedidos del turno" value={orders.length} /><Metric icon="♨" label="Pedidos abiertos" value={active.length} /><Metric icon="$" label="Venta capturada" value={money(store, sales)} /><Metric icon="⌖" label="Estaciones activas" value={new Set(active.flatMap(order => order.tickets?.map(ticket => ticket.station) || [])).size} /></section><section className="panel recent-panel"><div className="section-heading"><div><span className="eyebrow">MOVIMIENTO RECIENTE</span><h2>Últimos pedidos</h2></div><button className="text-button" onClick={onOrders}>Ver todos →</button></div>{orders.slice(0, 5).map(order => <OrderRow key={order.id} order={order} store={store} onOpen={() => onOpen(order)} />)}</section></>; }
function Metric({ icon, label, value }) { return <article className="metric-card"><span className="metric-icon green">{icon}</span><span className="metric-label">{label}</span><strong>{value}</strong></article>; }
function OrderRow({ order, store, onOpen }) { const status=orderStatus(order.status); return <button type="button" className={`order-row order-row-status-${status.key}`} onClick={onOpen}><span className="order-number">#{String(order.number).padStart(3, '0')}</span><span className="order-summary"><strong>{order.type === 'mesa' ? `Mesa ${order.table}` : order.customerName || typeLabel(order)}</strong><small>{new Intl.DateTimeFormat('es-MX',{hour:'2-digit',minute:'2-digit'}).format(new Date(order.createdAt))} · {order.items.length} partidas · {typeLabel(order)}</small></span><span className={`status-pill status-${status.key}`}>{status.label}</span><strong className="order-amount">{money(store, subtotal(order))}</strong></button>; }

function Cash({ store, onClose }) {
  const [counted, setCounted] = useState(''); const session = store.activeCashSession;
  const paid = store.orders.filter(order => order.paid && order.payment?.cashSessionId === session.id); const cash = paid.filter(order => order.payment.method === 'Efectivo').reduce((sum, order) => sum + Number(order.payment.total || 0), 0); const sales = paid.reduce((sum, order) => sum + Number(order.payment.total || 0), 0); const expected = Number(session.openingCash || 0) + cash; const expectedTurnTotal = Number(session.openingCash || 0) + sales;
  return <><section className="page-heading"><div><span className="eyebrow">TURNO DE {session.openedBy || 'pizzas'}</span><h1>Caja abierta</h1><p>Controla ventas y registra el corte al terminar el día.</p></div><span className="cash-status-pill">Abierta</span></section><div className="cash-layout"><section className="panel cash-panel"><div className="section-heading"><div><span className="eyebrow">RESUMEN ACTUAL</span><h2>Movimiento del turno</h2></div></div><div className="cash-report-grid"><article><span>Fondo para cambio</span><strong>{money(store, session.openingCash)}</strong></article><article><span>Ventas cobradas</span><strong>{money(store, sales)}</strong></article><article><span>Ventas en efectivo</span><strong>{money(store, cash)}</strong></article><article><span>Efectivo esperado en caja</span><strong>{money(store, expected)}</strong></article><article className="cash-total-turn"><span>Total esperado del turno</span><strong>{money(store, expectedTurnTotal)}</strong><small>Cambio + ventas en efectivo, tarjeta y transferencia</small></article><article><span>Pedidos cobrados</span><strong>{paid.length}</strong></article></div></section><section className="panel cash-panel cash-close-panel"><div className="panel-title"><span className="settings-icon gold-icon">▣</span><div><h2>Corte de caja</h2><p>Cuenta el efectivo físicamente antes de cerrar.</p></div></div><form className="cash-count-form" onSubmit={event => { event.preventDefault(); onClose(Number(counted)); }}><label className="cash-count-label"><span>Efectivo contado</span><small>Suma todo el efectivo disponible en caja.</small><span className="cash-count-input"><b aria-hidden="true">$</b><input type="number" min="0" step="1" inputMode="decimal" placeholder="0" value={counted} onChange={event => setCounted(event.target.value)} required autoFocus /><em>MXN</em></span></label><div className="cash-count-reference"><span><b>Referencia de efectivo</b><small>{money(store,session.openingCash)} de cambio + {money(store,cash)} de ventas en efectivo</small></span><strong>{money(store, expected)} en caja</strong></div><div className="cash-turn-reference"><span>Total esperado del turno</span><strong>{money(store,expectedTurnTotal)}</strong></div><button className="button button-primary button-full" disabled={counted === ''}>Registrar corte del día <span>→</span></button></form></section></div></>;
}

function Orders({ store, orders, onNew, onOpen }) {
  const groups = useMemo(() => Object.entries(orders.reduce((result, order) => { const key = new Intl.DateTimeFormat('es-MX',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(new Date(order.createdAt)); (result[key] ||= []).push(order); return result; }, {})), [orders]);
  return <><section className="page-heading"><div><span className="eyebrow">VENTA Y SERVICIO</span><h1>Pedidos</h1><p>Historial de mesa, domicilio y recogida.</p></div><button className="button button-primary" onClick={onNew}>＋ Nuevo pedido</button></section><section className="panel orders-section">{groups.map(([day, dayOrders]) => <section className="day-order-group" key={day}><h3>{day}</h3><div className="orders-list">{dayOrders.map(order => <OrderRow key={order.id} order={order} store={store} onOpen={() => onOpen(order)} />)}</div></section>)}</section></>;
}

function Kitchen({ store, orders, onRefresh, onOpen, toast }) {
  const active = orders.filter(hasPendingCommand);
  const finish = async (order, station) => { try { await api.updateOrder(order.id, { ticketStation: station, status: 'listo' }); await onRefresh(); toast(`${station} terminado.`); } catch (error) { toast(error.message, 'error'); } };
  return <><section className="page-heading"><div><span className="eyebrow">PREPARACIÓN EN CURSO</span><h1>Comandas</h1><p>Solo se muestran las partidas del turno activo.</p></div><button className="button button-secondary" onClick={onRefresh}>↻ Actualizar</button></section><div className="kitchen-columns">{stations.map(station => <section className="kitchen-column" key={station}><header><h2>{station}</h2><span className="heading-count">{active.filter(order => order.items.some(item => item.station === station)).length}</span></header>{active.filter(order => order.items.some(item => item.station === station)).map(order => <article className="kitchen-ticket" key={`${order.id}-${station}`}><div className="kitchen-ticket-head"><strong>{typeLabel(order)}{order.type === 'mesa' ? ` · Mesa ${order.table}` : ''}</strong><span>#{String(order.number).padStart(3,'0')}</span></div>{order.items.filter(item => item.station === station).map(item => <div className="kitchen-item" key={item.lineId}><strong>{item.quantity} × {item.name}</strong><small>{formatTicketDetails(item)}</small></div>)}<div className="ticket-actions"><button className="button button-secondary" onClick={() => onOpen(order)}>Ver pedido</button><button className="button button-success" onClick={() => finish(order, station)}>Terminar</button></div></article>)}</section>)}</div></>;
}

function Catalog({ store, onRefresh, toast, onModal }) {
  const [categoryFilter, setCategoryFilter] = useState('all');
  const [subcategoryFilter, setSubcategoryFilter] = useState('all');
  const toggle = async product => { try { await api.saveCatalog(store.catalog.map(item => item.id === product.id ? { ...item, active: item.active === false } : item)); await onRefresh(); toast('Disponibilidad actualizada.'); } catch (error) { toast(error.message, 'error'); } };
  const parentLabel = product => productCategories.find(category => category.id === productParentCategory(product))?.label || productParentCategory(product);
  const firstActivePizzaSize = configuredPizzaSizes(store.settings).find(size => size.active !== false);
  const filteredByCategory = categoryFilter === 'all' ? store.catalog : store.catalog.filter(product => productParentCategory(product) === categoryFilter);
  const subcategoryOptions = [...new Set(filteredByCategory.map(productSubcategory))].sort((left, right) => left.localeCompare(right, 'es-MX'));
  const visibleProducts = subcategoryFilter === 'all' ? filteredByCategory : filteredByCategory.filter(product => productSubcategory(product) === subcategoryFilter);
  const changeCategoryFilter = value => { setCategoryFilter(value); setSubcategoryFilter('all'); };
  const addProduct = () => {
    const parentCategory = categoryFilter === 'all' ? 'pizzas' : categoryFilter;
    const definition = productCategories.find(category => category.id === parentCategory) || productCategories[0];
    const subcategory = subcategoryFilter === 'all' ? definition.subcategories[0] : subcategoryFilter;
    const sizeDefinitions = configuredPizzaSizes(store.settings);
    const draft = normalizeProductHierarchy({
      id:`manual-${crypto.randomUUID()}`, name:'', parentCategory, subcategory,
      kind:parentCategory === 'pizzas' ? 'pizza' : 'dish', price:0,
      prices:parentCategory === 'pizzas' ? Object.fromEntries(sizeDefinitions.map(size => [size.id,pizzaPriceForSubcategory(size,subcategory)])) : {},
      description:'', choices:[], choiceGroups:[], variants:[], active:true
    });
    onModal({ type:'add-product', product:draft });
  };
  return <><section className="page-heading"><div><span className="eyebrow">CONFIGURACIÓN DE LA CARTA</span><h1>Mi carta</h1><p>Productos del menú local actual.</p></div><button type="button" className="button button-primary" onClick={addProduct}>＋ Agregar platillo</button></section><section className="panel catalog-panel"><div className="catalog-filter-bar"><label><span>Categoría</span><Combo value={categoryFilter} onChange={changeCategoryFilter} options={[{value:'all',label:'Todas las categorías'},...productCategories.map(category => ({value:category.id,label:category.label}))]} /></label><label><span>Subcategoría</span><Combo value={subcategoryFilter} onChange={setSubcategoryFilter} options={[{value:'all',label:'Todas las subcategorías'},...subcategoryOptions.map(value => ({value,label:value}))]} /></label><small>{visibleProducts.length} {visibleProducts.length === 1 ? 'producto' : 'productos'}</small></div><div className="catalog-table-head"><span>PLATILLO</span><span>CATEGORÍA</span><span>SUBCATEGORÍA</span><span>PRECIO BASE</span><span>DISPONIBLE</span><span>ACCIONES</span></div><div className="catalog-list">{visibleProducts.map(product => <div className={`catalog-row ${product.active === false ? 'is-unavailable' : ''}`} key={product.id}><span className="catalog-name"><span className="catalog-mini-icon"><img className="dish-icon" src={`/assets/icons/${dishIcon(product)}.svg`} alt="" /></span><span><strong>{product.name}</strong><small>{product.description || 'Sin descripción'}</small></span></span><span className="catalog-category">{parentLabel(product)}</span><span className="catalog-subcategory">{productSubcategory(product)}</span><span className="catalog-price">{money(store, product.kind === 'pizza' ? product.prices?.[firstActivePizzaSize?.id] : product.price)}</span><button type="button" className={`availability-toggle ${product.active === false ? '' : 'is-on'}`} role="switch" aria-checked={product.active !== false} onClick={() => toggle(product)}><span />{product.active === false ? 'Pausado' : 'Activo'}</button><span className="catalog-actions"><button type="button" className="catalog-action edit" onClick={() => onModal({ type:'edit-product', product })} aria-label={`Editar ${product.name}`}>✎ <span>Editar</span></button><button type="button" className="catalog-action delete" onClick={() => onModal({ type:'delete-product', product })} aria-label={`Eliminar ${product.name}`}>⌫ <span>Eliminar</span></button></span></div>)}{visibleProducts.length === 0 && <div className="catalog-empty">No hay productos en esta combinación.</div>}</div></section></>;
}

function Settings({ store, onRefresh, toast }) {
  const [settings, setSettings] = useState(store.settings);
  const closedSessions = (store.cashSessions || []).filter(session => session.status === 'cerrada');
  const save = async event => { event.preventDefault(); try { await api.saveSettings(settings); await onRefresh(); toast('Ajustes guardados.'); } catch (error) { toast(error.message, 'error'); } };
  return <><section className="page-heading"><div><span className="eyebrow">EQUIPO Y OPERACIÓN</span><h1>Ajustes</h1><p>Configuración local del restaurante.</p></div></section><div className="settings-grid"><section className="panel settings-panel"><div className="panel-title"><span className="settings-icon">⚙</span><div><h2>Datos del restaurante</h2><p>Se muestran en tickets y operación.</p></div></div><form className="settings-form" onSubmit={save}><label>Nombre<input value={settings.restaurantName || ''} onChange={event => setSettings({...settings, restaurantName:event.target.value})} /></label><label>Teléfono<input value={settings.phone || ''} onChange={event => setSettings({...settings, phone:event.target.value})} /></label><label>Número de mesas<input type="number" value={settings.tableCount || 12} onChange={event => setSettings({...settings, tableCount:Number(event.target.value)})} /></label><label>Ancho del ticket<Combo value={settings.paperWidth || '58mm'} onChange={paperWidth => setSettings({...settings,paperWidth})} options={[{value:'58mm',label:'58 mm'},{value:'80mm',label:'80 mm'}]} /></label><button className="button button-primary">Guardar ajustes</button></form></section><section className="panel settings-panel"><div className="panel-title"><span className="settings-icon gold-icon">⇩</span><div><h2>Reportes y respaldo</h2><p>Descarga los datos del sistema.</p></div></div><div className="export-actions"><a className="button button-secondary" href="/api/export/pdf">Exportar PDF</a><a className="button button-secondary" href="/api/export/excel">Exportar Excel</a><a className="text-button" href="/api/export">Respaldo JSON</a></div>{closedSessions.length > 0 && <div className="cash-report-history"><strong>Cortes anteriores</strong>{closedSessions.map(session => <a key={session.id} href={`/api/cash-sessions/${session.id}/report.pdf`} download><span>{new Intl.DateTimeFormat('es-MX',{dateStyle:'medium'}).format(new Date(session.closedAt))}</span><b>Descargar PDF</b></a>)}</div>}</section>{store.currentUser?.role === 'admin' && <AdminSettings store={store} onRefresh={onRefresh} toast={toast} />}</div></>;
}

function AdminSettings({ store, onRefresh, toast }) {
  const [inventory, setInventory] = useState(store.rawMaterials || []);
  const [passwordUser, setPasswordUser] = useState(store.currentUser?.username || store.users[0]?.username || '');
  useEffect(() => setInventory(store.rawMaterials || []), [store.rawMaterials]);
  const saveInventory = async items => { const next = items || inventory; await api.saveRawMaterials(next, store.rawMaterialCategories || []); setInventory(next); await onRefresh(); };
  const addMaterial = async event => { event.preventDefault(); const form = new FormData(event.currentTarget); const material = { id:crypto.randomUUID(),name:String(form.get('name') || '').trim(),category:String(form.get('category') || '').trim(),stock:Number(form.get('stock')) }; try { if (!material.name || !material.category) throw new Error('Escribe el nombre y la categoría de la materia prima.'); const next = [...inventory,material]; await saveInventory(next); event.currentTarget.reset(); toast(`${material.name} agregado al inventario.`); } catch (error) { toast(error.message,'error'); } };
  const persistInventory = async () => { try { await saveInventory(); toast('Existencias actualizadas.'); } catch (error) { toast(error.message,'error'); } };
  const addUser = async event => { event.preventDefault(); const data = new FormData(event.currentTarget); const password = String(data.get('password') || ''); try { if (password !== String(data.get('confirmPassword') || '')) throw new Error('Las contraseñas no coinciden.'); await api.createUser({username:data.get('username'),password}); await onRefresh(); event.currentTarget.reset(); toast('Administrador agregado.'); } catch(error) { toast(error.message,'error'); } };
  const changePassword = async event => { event.preventDefault(); const data = new FormData(event.currentTarget); const newPassword = String(data.get('newPassword') || ''); try { if (newPassword !== String(data.get('confirmPassword') || '')) throw new Error('La nueva contraseña y su confirmación no coinciden.'); await api.changePassword({username:passwordUser,currentPassword:data.get('currentPassword'),newPassword}); event.currentTarget.reset(); toast(`Contraseña de ${passwordUser} actualizada.`); } catch(error) { toast(error.message,'error'); } };
  return <><section className="panel settings-panel admin-accounts-panel"><div className="panel-title"><span className="settings-icon">◉</span><div><h2>Administradores</h2><p>Todas las cuentas tienen acceso administrativo.</p></div></div><div className="user-role-list">{store.users.map(user => <span key={user.username}><strong>{user.username}</strong><small>Administrador</small></span>)}</div><div className="admin-account-forms"><form className="settings-form admin-user-form" onSubmit={addUser}><div className="account-form-heading"><strong>Agregar administrador</strong><small>La cuenta tendrá acceso completo al sistema.</small></div><label>Usuario<input name="username" minLength="3" maxLength="30" autoComplete="off" required /></label><label>Contraseña<input name="password" type="password" minLength="10" maxLength="128" autoComplete="new-password" required /></label><label>Confirmar contraseña<input name="confirmPassword" type="password" minLength="10" maxLength="128" autoComplete="new-password" required /></label><small className="password-help">Mínimo 10 caracteres, con mayúscula, minúscula y número.</small><button className="button button-secondary">Agregar administrador</button></form><form className="settings-form password-change-form" onSubmit={changePassword}><div className="account-form-heading"><strong>Cambiar contraseña</strong><small>Se requiere la contraseña actual del administrador en sesión.</small></div><label>Cuenta<Combo value={passwordUser} onChange={setPasswordUser} options={store.users.map(user => ({value:user.username,label:user.username}))} /></label><label>Contraseña actual<input name="currentPassword" type="password" autoComplete="current-password" required /></label><label>Nueva contraseña<input name="newPassword" type="password" minLength="10" maxLength="128" autoComplete="new-password" required /></label><label>Confirmar nueva contraseña<input name="confirmPassword" type="password" minLength="10" maxLength="128" autoComplete="new-password" required /></label><small className="password-help">Mínimo 10 caracteres, con mayúscula, minúscula y número.</small><button className="button button-primary">Actualizar contraseña</button></form></div></section><section className="panel settings-panel raw-materials-panel"><div className="panel-title"><span className="settings-icon">▤</span><div><h2>Inventario de materias primas</h2><p>Registra insumos independientes de los platillos.</p></div></div><form className="raw-material-form" onSubmit={addMaterial}><label>Nombre<input name="name" placeholder="Ej. Harina" maxLength="100" required /></label><label>Categoría<input name="category" list="raw-material-categories" placeholder="Ej. Abarrotes" maxLength="80" required /><datalist id="raw-material-categories">{(store.rawMaterialCategories || []).map(category => <option value={category} key={category} />)}</datalist></label><label>Existencias<input name="stock" type="number" min="0" step="any" defaultValue="0" required /></label><button className="button button-primary">＋ Agregar materia prima</button></form>{(store.rawMaterialCategories || []).length > 0 && <div className="raw-material-categories"><span>Categorías guardadas</span>{store.rawMaterialCategories.map(category => <b key={category}>{category}</b>)}</div>}{inventory.length === 0 ? <div className="inventory-empty"><span>▤</span><strong>Inventario vacío</strong><p>Agrega la primera materia prima con el formulario superior.</p></div> : <><div className="raw-material-list"><div className="raw-material-head"><span>Materia prima</span><span>Categoría</span><span>Existencias</span></div>{inventory.map(material => <div className="raw-material-row" key={material.id}><strong>{material.name}</strong><span>{material.category}</span><input type="number" min="0" step="any" aria-label={`Existencias de ${material.name}`} value={material.stock} onChange={event => setInventory(current => current.map(item => item.id === material.id ? {...item,stock:Number(event.target.value)} : item))} /></div>)}</div><button type="button" className="button button-secondary save-raw-materials" onClick={persistInventory}>Guardar existencias</button></>}</section></>;
}

function NewOrder({ store, draft, setDraft, onModal, onSend, onBackToOrder, onOpenOrder }) {
  const [category, setCategory] = useState('all'); const [validation, setValidation] = useState({ message:'', fields:[] }); const [sending, setSending] = useState(false); const products = selectableProducts(store.catalog, store.settings); const groups = [...new Set(products.flatMap(product => product.categories || [product.category]).filter(Boolean))];
  const currentOrders = store.orders.filter(order => isOpen(order) && order.type === 'mesa'); const tables = new Map(currentOrders.map(order => [String(order.table), order])); const tableCount = Number(store.settings.tableCount || 12);
  const visible = products.filter(product => category === 'all' || (product.categories || [product.category]).includes(category));
  const existingOrder = draft.existingOrderId ? store.orders.find(order => order.id === draft.existingOrderId) : null;
  const update = changes => { setValidation({ message:'', fields:[] }); setDraft({ ...draft, ...changes }); };
  const fail = (message, fields = []) => setValidation({ message, fields });
  const clear = () => setDraft(draft.existingOrderId ? { ...draft, items:[], orderNote:'' } : emptyDraft());
  const send = async () => {
    if (!draft.items.length) return fail('Agrega al menos un platillo antes de enviar el pedido.');
    if (!draft.existingOrderId && draft.type === 'mesa' && !draft.table) return fail('Selecciona una mesa para continuar.', ['table']);
    if (!draft.existingOrderId && (draft.type === 'domicilio' || draft.type === 'recoger')) {
      if (!String(draft.customerName || '').trim()) return fail('Escribe el nombre del cliente.', ['customerName']);
      if (String(draft.phone || '').replace(/\D/g,'').length !== 10) return fail('Escribe un teléfono de exactamente 10 dígitos.', ['phone']);
      if (draft.type === 'domicilio' && !String(draft.address || '').trim()) return fail('Escribe la dirección de entrega.', ['address']);
    }
    try { setSending(true); await onSend({ ...draft, phone: phone(draft.phone), guests: Number(draft.guests || 0) }); }
    catch (error) { fail(error.message || 'No se pudo guardar el pedido.'); }
    finally { setSending(false); }
  };
  return <><section className="page-heading order-page-heading"><div>{draft.existingOrderId && <button type="button" className="back-link add-order-back" onClick={onBackToOrder}>← Regresar al pedido #{String(existingOrder?.number || '').padStart(3,'0')}</button>}<span className="eyebrow">{draft.existingOrderId ? 'PARTIDAS ADICIONALES' : 'CAPTURA RÁPIDA'}</span><h1>{draft.existingOrderId ? 'Agregar a pedido existente' : 'Nuevo pedido'}</h1><p>La comanda se imprime por estación al enviarla a cocina.</p></div><button className="button button-quiet" onClick={clear}>Limpiar</button></section><div className="order-composer"><section className="order-main-column"><article className="panel service-panel"><div className="panel-title"><span className="step-badge">01</span><div><h2>¿Cómo se servirá?</h2><p>Selecciona el tipo de pedido</p></div></div>{!draft.existingOrderId && <div className="service-options">{[['mesa','⌂','En mesa'],['domicilio','⌖','Domicilio'],['recoger','▱','Recoger aquí']].map(([type, symbol, title]) => <button key={type} className={`service-option ${draft.type === type ? 'selected' : ''}`} onClick={() => update({ type })}><span className="service-symbol">{symbol}</span><strong>{title}</strong><small>{type === 'mesa' ? 'Consumo en restaurante' : type === 'domicilio' ? 'Entrega al cliente' : 'Pedido telefónico o mostrador'}</small></button>)}</div>}{draft.type === 'mesa' ? (draft.existingOrderId ? <div className="existing-order-note">Mesa {draft.table} · {draft.guests} comensales. Solo agrega nuevas partidas.</div> : <><div className="table-select-heading"><strong>Selecciona mesa</strong><span>{tables.size} ocupadas · {tableCount-tables.size} libres</span></div><div className="table-grid">{Array.from({length:tableCount}, (_, index) => String(index+1)).map(number => { const busy = tables.get(number); return <button key={number} type="button" className={`table-card ${busy ? 'is-occupied' : 'is-free'} ${draft.table === number ? 'is-selected' : ''}`} aria-label={busy ? `Abrir pedido de la mesa ${number}` : `Seleccionar mesa ${number}`} onClick={() => busy ? onOpenOrder(busy) : update({ table:number })}><span className="table-number">{number}</span><strong>Mesa {number}</strong><span className="table-state"><i />{busy ? 'Ocupada · ver pedido' : 'Disponible'}</span></button>; })}</div><label className="field-label">Comensales<input type="number" min="1" max="30" value={draft.guests} onChange={event => update({guests:event.target.value})} /></label></>) : <ServiceContact draft={draft} update={update} invalidFields={validation.fields} />}{validation.message && <div className="order-form-alert" role="alert"><span>!</span><div><strong>Revisa el pedido</strong><p>{validation.message}</p></div></div>}</article><article className="panel menu-panel"><div className="panel-title"><span className="step-badge">02</span><div><h2>Agrega a la comanda</h2><p>La carta actualizada del restaurante</p></div></div><div className="category-tabs"><button className={`category-tab ${category === 'all' ? 'selected' : ''}`} onClick={() => setCategory('all')}>Todo</button>{groups.map(group => <button key={group} className={`category-tab ${category === group ? 'selected' : ''}`} onClick={() => setCategory(group)}>{categories[group] || group}</button>)}</div><div className="product-grid">{visible.map(product => <button className={`product-card ${product.kind?.includes('pizza') ? 'product-pizza' : ''}`} key={product.id} onClick={() => onModal({ type: product.kind === 'pizza-menu' ? 'pizza' : product.kind === 'beverage-menu' ? 'beverage' : 'dish', product })}><span className="product-art"><img className="dish-icon" src={`/assets/icons/${dishIcon(product)}.svg`} alt="" /></span><span className="product-card-copy"><span className="product-group">{product.group || categories[product.category]}</span><strong>{product.name}</strong><small>{product.description || 'Agregar al pedido'}</small><span className="product-price">{money(store, product.price)}</span></span><span className="add-indicator">＋</span></button>)}</div></article></section><aside className="panel order-summary-panel"><div className="summary-heading"><div><span className="eyebrow">COMANDA ACTUAL</span><h2>Tu pedido</h2></div><span className="cart-count">{draft.items.reduce((sum,item) => sum + Number(item.quantity),0)}</span></div>{draft.items.length ? <><div className="cart-items">{draft.items.map(item => <div className="cart-item" key={item.lineId}><div className="cart-item-top"><span className="cart-category">{item.station}</span><button className="icon-button" onClick={() => update({items:draft.items.filter(line => line.lineId !== item.lineId)})}>×</button></div><strong>{item.name}</strong><small>{item.details}</small><div className="cart-item-bottom"><div className="stepper stepper-small"><button onClick={() => update({items:draft.items.map(line => line.lineId===item.lineId ? {...line,quantity:Math.max(1,line.quantity-1)}:line)})}>−</button><span>{item.quantity}</span><button onClick={() => update({items:draft.items.map(line => line.lineId===item.lineId ? {...line,quantity:line.quantity+1}:line)})}>＋</button></div><strong>{money(store, Number(item.unitPrice)*Number(item.quantity))}</strong></div></div>)}</div><label className="summary-note">Nota general<textarea value={draft.orderNote} onChange={event => update({orderNote:event.target.value})} /></label><div className="summary-total"><span>Total</span><strong>{money(store, subtotal(draft))}</strong></div><button className="button button-primary button-full" disabled={sending} onClick={send}>{sending ? 'Enviando…' : draft.existingOrderId ? 'Enviar nuevas partidas →' : 'Enviar a cocina →'}</button></> : <div className="empty-state"><strong>Tu pedido está vacío</strong><p>Elige un platillo para comenzar.</p></div>}</aside></div></>;
}

function ServiceContact({ draft, update, invalidFields = [] }) { const invalid = field => invalidFields.includes(field); return <div className="service-fields delivery-fields"><label className={invalid('customerName') ? 'field-invalid' : ''}>Nombre del cliente<input aria-invalid={invalid('customerName')} value={draft.customerName} onChange={event => update({customerName:event.target.value})} /></label><label className={invalid('phone') ? 'field-invalid' : ''}>Teléfono<div className="phone-field"><b>+52</b><input aria-invalid={invalid('phone')} inputMode="numeric" maxLength="12" value={phone(draft.phone)} onChange={event => update({phone:phone(event.target.value)})} placeholder="999-999-9999" /></div><small>Ingresa exactamente 10 dígitos.</small></label>{draft.type === 'domicilio' && <label className={`address-field ${invalid('address') ? 'field-invalid' : ''}`}>Dirección<textarea aria-invalid={invalid('address')} value={draft.address} onChange={event => update({address:event.target.value})} /></label>}</div>; }

function OrderDetail({ store, order, onBack, onRefresh, onModal, toast, onAdd }) {
  if (!order) return <div className="empty-state"><strong>No encontramos el pedido.</strong></div>;
  const orderStations = stations.filter(station => order.items.some(item => item.station === station));
  const allReady = order.tickets?.length > 0 && order.tickets.every(ticket => ticket.status === 'listo');
  const finishAll = async () => { try { await api.updateOrder(order.id, { finishAllTickets:true }); await onRefresh(); toast('Toda la preparación fue terminada.'); } catch (error) { toast(error.message,'error'); } };
  const deliveryDispatched = order.type === 'domicilio' && ['en_ruta', 'entregado'].includes(order.status);
  const payable = isOpen(order) && allReady && (order.type !== 'domicilio' || deliveryDispatched);
  const dispatchDelivery = async () => { try { if (!printTicket(store, order, null, true)) return toast('Permite las ventanas emergentes para imprimir la cuenta de entrega.', 'error'); await api.updateOrder(order.id, { dispatchDelivery:true }); await onRefresh(); toast('Salida registrada y cuenta de entrega impresa.'); } catch (error) { toast(error.message,'error'); } };
  const cancel = () => onModal({ type:'cancel', order });
  const deliveryControl = order.type === 'domicilio' && !order.paid && isOpen(order) ? !allReady
    ? <p className="service-status-hint">Termina la preparación para habilitar la salida a domicilio.</p>
    : deliveryDispatched
      ? <div className="delivery-settlement"><div className="delivery-ready-note">⌖ Pedido en reparto · pago pendiente</div><button className="button button-secondary button-full" onClick={() => printTicket(store, order, null, true)}>▤ Reimprimir cuenta de entrega</button><p>Finaliza el cobro cuando el repartidor regrese y entregue el dinero a caja.</p></div>
      : <button className="button button-secondary button-full delivery-progress" onClick={dispatchDelivery}>⌖ Marcar salida e imprimir cuenta</button>
    : null;
  const canAddItems = isOpen(order) && !deliveryDispatched;
  const closedAtCashCut = order.status === 'cerrado_turno';
  const visibleStatus = orderStatus(order.status);
  const pickupNotice = order.type === 'recoger' && allReady && !order.paid && isOpen(order) ? <p className="pickup-ready-note">✓ Pedido listo. Llama manualmente al cliente para que pase a recogerlo.</p> : null;
  const pickupContact = order.type === 'recoger' ? <section className="panel pickup-contact-panel"><div className="pickup-contact-heading"><div><span className="eyebrow">CONTACTO DEL PEDIDO</span><h2>Datos del cliente</h2></div><span className="pickup-call-tag">☎ Llama al cliente</span></div><div className="pickup-contact-data"><span className="pickup-contact-icon" aria-hidden="true">☺</span><div><small>Nombre</small><strong>{order.customerName || 'Cliente'}</strong><small>Teléfono</small><a href={`tel:+52${String(order.phone || '').replace(/\D/g,'')}`}>+52 {phone(order.phone)}</a></div></div><div className="pickup-contact-actions"><a className="button button-secondary" href={`tel:+52${String(order.phone || '').replace(/\D/g,'')}`}>☎ Llamar</a><button type="button" className="button button-secondary pickup-message-button" disabled title="Disponible cuando se configure WhatsApp">✆ Mandar mensaje <small>Próximamente</small></button></div></section> : null;
  return <><section className="page-heading"><div><button className="back-link" onClick={onBack}>← Volver a pedidos</button><span className="eyebrow">PEDIDO</span><h1>Pedido #{String(order.number).padStart(3,'0')}</h1><p>{typeLabel(order)}{order.type === 'mesa' ? ` · Mesa ${order.table} · ${order.guests} comensales` : ''}</p></div><span className={`status-pill status-${visibleStatus.key}`}>{visibleStatus.label}</span></section><div className="detail-grid"><section className="panel detail-items-panel"><div className="section-heading"><div><span className="eyebrow">{order.items.length} PARTIDAS</span><h2>Platillos del pedido</h2></div></div><div className="detail-items">{order.items.map(item => <div className="detail-item" key={item.lineId}><span className="detail-quantity">{item.quantity}×</span><div><strong>{item.name}</strong><small>{formatTicketDetails(item)}</small></div><strong>{money(store, Number(item.unitPrice)*Number(item.quantity))}</strong></div>)}</div><div className="detail-total"><span>Total</span><strong>{money(store,subtotal(order))}</strong></div></section><aside className="detail-side"><section className="panel production-panel"><div className="section-heading"><div><span className="eyebrow">PRODUCCIÓN</span><h2>Tickets por estación</h2></div></div>{orderStations.map(station => { const ticket=order.tickets.find(item=>item.station===station); return <article className="station-row" key={station}><div><strong>{station}</strong><small>{ticket?.status === 'listo' ? 'Terminado' : 'Pendiente'}</small></div><div className="station-actions"><button type="button" className="button button-print station-print-button" onClick={() => printTicket(store, order, station)}>▤ Reimprimir</button>{ticket?.status === 'listo' && <span className="ready-check" aria-label="Terminado">✓</span>}</div></article>; })}<button type="button" className={`button button-full production-finish-button ${allReady ? 'button-success' : 'button-primary'}`} disabled={allReady || !isOpen(order)} onClick={finishAll}>{allReady ? '✓ Toda la preparación terminada' : '✓ Terminar todos los platillos'}</button></section>{pickupContact}<section className="panel order-payment-panel"><span className="eyebrow">CIERRE DE VENTA</span><h2>{order.paid ? 'Pedido cobrado' : order.status === 'cancelado' ? 'Pedido cancelado' : closedAtCashCut ? 'Cerrado al finalizar el turno' : deliveryDispatched ? 'Liquidación del repartidor' : '¿Todo listo?'}</h2>{order.cancellation && <p>Motivo: {order.cancellation.reason}</p>}{closedAtCashCut && <p className="service-status-hint">Este pedido quedó sin cobro y fue cerrado automáticamente durante el corte de caja. Ya no ocupa una mesa.</p>}{canAddItems && <button className="button button-secondary button-full" onClick={() => onAdd(order)}>＋ Agregar partidas</button>}{deliveryControl}{pickupNotice}{order.paid ? <><p>Pago registrado · {order.payment.method} · {money(store,order.payment.total)}</p>{store.currentUser?.role === 'admin' && <button className="text-button cancel-order-button" onClick={cancel}>Cancelar y reembolsar</button>}</> : isOpen(order) && <><button className="button button-primary button-full" disabled={!payable} onClick={() => onModal({type:'payment',order})}>{payable ? order.type === 'domicilio' ? `Registrar dinero recibido · ${money(store,subtotal(order))}` : `Cobrar · ${money(store,subtotal(order))}` : order.type === 'domicilio' && allReady ? 'Marca la salida para continuar' : 'Esperando cierre del servicio'}</button><button className="text-button cancel-order-button" onClick={cancel}>Cancelar este pedido</button></>}</section></aside></div></>;
}

function ProductModal({ store, modal, setModal, addItem, onRefresh, toast }) {
  if (modal.type === 'payment') return <PaymentModal store={store} order={modal.order} close={() => setModal(null)} onRefresh={onRefresh} toast={toast} />;
  if (modal.type === 'cancel') return <CancelOrderModal store={store} order={modal.order} close={() => setModal(null)} onRefresh={onRefresh} toast={toast} />;
  if (modal.type === 'add-product') return <ProductEditorModal store={store} product={modal.product} creating close={() => setModal(null)} onRefresh={onRefresh} toast={toast} />;
  if (modal.type === 'edit-product') return <ProductEditorModal store={store} product={modal.product} close={() => setModal(null)} onRefresh={onRefresh} toast={toast} />;
  if (modal.type === 'delete-product') return <DeleteProductModal store={store} product={modal.product} close={() => setModal(null)} onRefresh={onRefresh} toast={toast} />;
  if (modal.type === 'pizza') return <PizzaModal store={store} product={modal.product} close={() => setModal(null)} addItem={addItem} />;
  return <DishModal store={store} product={modal.product} type={modal.type} close={() => setModal(null)} addItem={addItem} />;
}

function MoneyInput({ value, onChange, required = false, ariaLabel }) {
  return <span className="money-input"><span className="money-symbol" aria-hidden="true">$</span><input type="number" min="0" step="1" value={value} onChange={onChange} required={required} aria-label={ariaLabel} /><span className="money-currency">MXN</span></span>;
}

function PizzaSizeManager({ store, close, onSaved, onRefresh, toast }) {
  const [sizes, setSizes] = useState(() => configuredPizzaSizes(store.settings));
  const [newSize, setNewSize] = useState({ name:'', detail:'', basePrice:'', especialidades:'', gourmet:'', cheeseRimPrice:'' });
  const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const change = (id, changes) => { setSizes(current => current.map(size => size.id === id ? { ...size, ...changes } : size)); setError(''); };
  const remove = id => { setSizes(current => current.filter(size => size.id !== id)); setError(''); };
  const add = event => {
    event.preventDefault(); const name = newSize.name.trim();
    if (!name || !newSize.basePrice) return setError('Escribe el nombre y precio base del nuevo tamaño.');
    const rootId = name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es-MX').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,24) || 'tamano';
    let id = rootId; let suffix = 2; while (sizes.some(size => size.id === id)) id = `${rootId}-${suffix++}`;
    setSizes(current => [...current, { id, name, detail:newSize.detail.trim(), active:true, basePrice:Number(newSize.basePrice), adjustments:{ Especialidades:Number(newSize.especialidades || 0), Gourmet:Number(newSize.gourmet || 0) }, cheeseRimPrice:Number(newSize.cheeseRimPrice || 0) }]);
    setNewSize({ name:'', detail:'', basePrice:'', especialidades:'', gourmet:'', cheeseRimPrice:'' }); setError('');
  };
  const save = async () => {
    if (!sizes.length) return setError('Debe permanecer al menos un tamaño.');
    if (!sizes.some(size => size.active !== false)) return setError('Habilita al menos un tamaño para tomar pedidos.');
    try { setSaving(true); const result = await api.savePizzaSizes(sizes); const refreshed = await onRefresh(); onSaved(refreshed, result); toast('Tamaños y precios de pizza actualizados.'); }
    catch (exception) { setError(exception.message); setSaving(false); }
  };
  return <Modal onClose={close} title="Administrar tamaños de pizza"><div className="pizza-size-manager"><div className="editor-modal-header"><span className="eyebrow">CONFIGURACIÓN GENERAL</span><h2>Tamaños y precios base</h2><p>Los incrementos se suman al precio base para Especialidades y Gourmet.</p></div><div className="pizza-size-list">{sizes.map(size => <article className={`pizza-size-row ${size.active === false ? 'is-disabled' : ''}`} key={size.id}><div className="pizza-size-identity"><label>Nombre<input value={size.name} maxLength="40" onChange={event => change(size.id,{name:event.target.value})} /></label><label>Detalle<input value={size.detail} maxLength="80" placeholder="Ej. 45 cm · 20 rebanadas" onChange={event => change(size.id,{detail:event.target.value})} /></label></div><div className="pizza-size-pricing"><label>Base Clásicas<MoneyInput value={size.basePrice} ariaLabel={`Precio base de ${size.name}`} onChange={event => change(size.id,{basePrice:Number(event.target.value)})} /></label><label>+ Especialidades<MoneyInput value={size.adjustments.Especialidades} ariaLabel={`Incremento Especialidades de ${size.name}`} onChange={event => change(size.id,{adjustments:{...size.adjustments,Especialidades:Number(event.target.value)}})} /></label><label>+ Gourmet<MoneyInput value={size.adjustments.Gourmet} ariaLabel={`Incremento Gourmet de ${size.name}`} onChange={event => change(size.id,{adjustments:{...size.adjustments,Gourmet:Number(event.target.value)}})} /></label><label>Orilla de queso<MoneyInput value={size.cheeseRimPrice} ariaLabel={`Precio de orilla de queso para ${size.name}`} onChange={event => change(size.id,{cheeseRimPrice:Number(event.target.value)})} /></label></div><div className="pizza-size-actions"><button type="button" className={`size-status-button ${size.active !== false ? 'is-active' : ''}`} onClick={() => change(size.id,{active:size.active === false})}>{size.active === false ? 'Deshabilitado' : 'Habilitado'}</button><button type="button" className="size-delete-button" onClick={() => remove(size.id)}>Eliminar</button></div></article>)}</div><form className="new-pizza-size" onSubmit={add}><div><span className="eyebrow">NUEVO TAMAÑO</span><strong>Añadir tamaño</strong></div><label>Nombre<input value={newSize.name} onChange={event => setNewSize({...newSize,name:event.target.value})} placeholder="Ej. Jumbo" maxLength="40" required /></label><label>Detalle<input value={newSize.detail} onChange={event => setNewSize({...newSize,detail:event.target.value})} placeholder="45 cm · 20 rebanadas" maxLength="80" /></label><label>Precio base<MoneyInput value={newSize.basePrice} ariaLabel="Precio base del nuevo tamaño" onChange={event => setNewSize({...newSize,basePrice:event.target.value})} required /></label><label>+ Especialidades<MoneyInput value={newSize.especialidades} ariaLabel="Incremento para Especialidades" onChange={event => setNewSize({...newSize,especialidades:event.target.value})} /></label><label>+ Gourmet<MoneyInput value={newSize.gourmet} ariaLabel="Incremento para Gourmet" onChange={event => setNewSize({...newSize,gourmet:event.target.value})} /></label><label>Orilla de queso<MoneyInput value={newSize.cheeseRimPrice} ariaLabel="Precio de orilla de queso" onChange={event => setNewSize({...newSize,cheeseRimPrice:event.target.value})} /></label><button className="button button-secondary">＋ Añadir</button></form>{error && <div className="auth-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={close}>Cancelar</button><button type="button" className="button button-primary" disabled={saving} onClick={save}>{saving ? 'Guardando…' : 'Guardar tamaños y precios'}</button></div></div></Modal>;
}

function ProductEditorModal({ store, product, creating = false, close, onRefresh, toast }) {
  const [draftProduct, setDraftProduct] = useState(() => normalizeProductHierarchy(structuredClone(product)));
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [managingSizes, setManagingSizes] = useState(false);
  const sizeDefinitions = configuredPizzaSizes(store.settings);
  const firstActiveSize = sizeDefinitions.find(size => size.active !== false) || sizeDefinitions[0];
  const update = changes => { setDraftProduct(current => ({ ...current, ...changes })); setError(''); };
  const parentCategory = productParentCategory(draftProduct);
  const categoryDefinition = productCategories.find(category => category.id === parentCategory) || productCategories[0];
  const subcategories = [...new Set([
    ...categoryDefinition.subcategories,
    ...store.catalog.filter(item => productParentCategory(item) === parentCategory).map(productSubcategory),
    productSubcategory(draftProduct)
  ].filter(Boolean))];
  const changeCategory = nextParentCategory => {
    const definition = productCategories.find(category => category.id === nextParentCategory) || productCategories[0];
    const subcategory = definition.subcategories[0];
    setDraftProduct(current => {
      const existingPrice = Number(current.price ?? current.prices?.mediana ?? 0);
      const next = nextParentCategory === 'pizzas'
        ? { ...current, parentCategory:nextParentCategory, subcategory, kind:'pizza', prices:Object.fromEntries(sizeDefinitions.map(size => [size.id, pizzaPriceForSubcategory(size, subcategory)])), price:pizzaPriceForSubcategory(sizeDefinitions.find(size => size.active !== false) || sizeDefinitions[0], subcategory) }
        : { ...current, parentCategory:nextParentCategory, subcategory, kind:current.kind === 'supplement' ? 'supplement' : 'dish', price:existingPrice };
      return normalizeProductHierarchy(next);
    });
    setError('');
  };
  const changeSubcategory = subcategory => setDraftProduct(current => normalizeProductHierarchy({ ...current, subcategory, ...(productParentCategory(current) === 'pizzas' ? { prices:Object.fromEntries(sizeDefinitions.map(size => [size.id,pizzaPriceForSubcategory(size,subcategory)])), price:pizzaPriceForSubcategory(sizeDefinitions.find(size => size.active !== false) || sizeDefinitions[0],subcategory) } : {}) }));
  const save = async event => {
    event.preventDefault();
    if (!String(draftProduct.name || '').trim()) return setError('Escribe el nombre del producto.');
    const normalized = normalizeProductHierarchy(draftProduct);
    const repeated = store.catalog.some(item => item.id !== normalized.id && productParentCategory(item) === productParentCategory(normalized) && String(item.name).trim().toLocaleLowerCase('es-MX') === String(normalized.name).trim().toLocaleLowerCase('es-MX'));
    if (repeated) return setError('Ya existe un producto con ese nombre en la categoría seleccionada.');
    const basePrice = normalized.kind === 'pizza' ? Number(normalized.prices?.[firstActiveSize.id]) : Number(normalized.price);
    if (!Number.isFinite(basePrice) || basePrice < 0 || (creating && basePrice === 0)) return setError(creating ? 'El precio del nuevo producto debe ser mayor a cero.' : 'Revisa el precio del producto.');
    if (normalized.kind === 'pizza' && sizeDefinitions.some(size => !Number.isFinite(Number(normalized.prices?.[size.id])) || Number(normalized.prices[size.id]) < 0)) return setError('Captura un precio válido para cada tamaño de pizza.');
    try {
      setSaving(true);
      const updated = normalizeProductHierarchy({ ...normalized, name:String(normalized.name).trim(), description:String(normalized.description || '').trim() });
      await api.saveCatalog(creating ? [...store.catalog,updated] : store.catalog.map(item => item.id === product.id ? updated : item));
      await onRefresh(); close(); toast(creating ? `${updated.name} agregado a la carta.` : `${updated.name} actualizado.`);
    } catch (exception) { setError(exception.message); } finally { setSaving(false); }
  };
  if (managingSizes) return <PizzaSizeManager store={store} close={() => setManagingSizes(false)} onRefresh={onRefresh} toast={toast} onSaved={refreshed => { const updated = refreshed.catalog.find(item => item.id === product.id); if (updated) setDraftProduct(normalizeProductHierarchy(structuredClone(updated))); else { const refreshedSizes=configuredPizzaSizes(refreshed.settings); setDraftProduct(current => normalizeProductHierarchy({...current,prices:Object.fromEntries(refreshedSizes.map(size=>[size.id,current.prices?.[size.id] ?? pizzaPriceForSubcategory(size,productSubcategory(current))]))})); } setManagingSizes(false); }} />;
  return <Modal onClose={close} title={creating ? 'Agregar platillo' : `Editar ${product.name}`}><form className="product-editor-form" onSubmit={save}><div className="editor-modal-header"><span className="eyebrow">{creating ? 'NUEVO PRODUCTO' : 'AJUSTE DE PRODUCTO'}</span><h2>{creating ? 'Agregar a Mi carta' : `Editar ${product.name}`}</h2><p>{creating ? 'Define cómo aparecerá el platillo al capturar pedidos.' : 'Los cambios se aplicarán a los pedidos nuevos.'}</p></div><label className="field-label">Nombre<input value={draftProduct.name || ''} maxLength="100" onChange={event => update({name:event.target.value})} placeholder="Nombre del platillo" required autoFocus /></label><div className="product-hierarchy-fields"><label className="field-label">Categoría<Combo value={parentCategory} onChange={changeCategory} options={productCategories.map(category => ({value:category.id,label:category.label}))} /></label><label className="field-label">Subcategoría<Combo value={productSubcategory(draftProduct)} onChange={changeSubcategory} options={subcategories.map(value => ({value,label:value}))} /></label></div>{draftProduct.kind === 'pizza' ? <div className="editor-price-section"><div className="editor-section-heading"><span className="editor-section-label">Precios por tamaño</span><button type="button" className="text-button" onClick={() => setManagingSizes(true)}>Administrar tamaños →</button></div><div className="editor-prices">{sizeDefinitions.map(size => <label className={size.active === false ? 'is-disabled-size' : ''} key={size.id}>{size.name}{size.active === false && <small>Deshabilitado</small>}<MoneyInput value={draftProduct.prices?.[size.id] ?? pizzaPriceForSubcategory(size, productSubcategory(draftProduct))} ariaLabel={`Precio ${size.name} en pesos mexicanos`} onChange={event => update({prices:{...(draftProduct.prices || {}),[size.id]:Number(event.target.value)},price:size.id === firstActiveSize.id ? Number(event.target.value) : draftProduct.price})} required /></label>)}</div></div> : <><label className="field-label">Precio base<MoneyInput value={draftProduct.price ?? 0} ariaLabel="Precio base en pesos mexicanos" onChange={event => update({price:Number(event.target.value)})} required /></label>{draftProduct.variants?.length > 0 && <div className="editor-price-section"><span className="editor-section-label">Precios por presentación</span><div className="editor-prices">{draftProduct.variants.map((variant,index) => <label key={`${variant.label}-${index}`}>{variant.label}<MoneyInput value={variant.price ?? 0} ariaLabel={`Precio de ${variant.label} en pesos mexicanos`} onChange={event => update({variants:draftProduct.variants.map((item,itemIndex) => itemIndex === index ? {...item,price:Number(event.target.value)} : item)})} /></label>)}</div></div>}</>}<label className="field-label">Descripción o ingredientes<textarea rows="3" maxLength="500" value={draftProduct.description || ''} onChange={event => update({description:event.target.value})} placeholder="Describe el platillo y sus ingredientes principales" /></label><label className="editor-active"><input type="checkbox" checked={draftProduct.active !== false} onChange={event => update({active:event.target.checked})} />Disponible para pedidos</label>{error && <div className="auth-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={close}>Cancelar</button><button className="button button-primary" disabled={saving}>{saving ? 'Guardando…' : creating ? 'Agregar a la carta' : 'Guardar cambios'}</button></div></form></Modal>;
}

function DeleteProductModal({ store, product, close, onRefresh, toast }) {
  const [deleting, setDeleting] = useState(false); const [error, setError] = useState('');
  const remove = async () => { try { setDeleting(true); await api.saveCatalog(store.catalog.filter(item => item.id !== product.id)); await onRefresh(); close(); toast(`${product.name} eliminado de la carta.`, 'error'); } catch (exception) { setError(exception.message); setDeleting(false); } };
  return <Modal onClose={close} title={`Eliminar ${product.name}`}><div className="delete-product-modal"><span className="delete-product-icon">⌫</span><div><span className="eyebrow">ELIMINAR DE LA CARTA</span><h2>¿Eliminar {product.name}?</h2><p>Dejará de aparecer en Mi carta y en la captura de pedidos. Las ventas anteriores conservarán su información.</p></div>{error && <div className="auth-error" role="alert">{error}</div>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={close}>Conservar producto</button><button type="button" className="button button-danger" disabled={deleting} onClick={remove}>{deleting ? 'Eliminando…' : 'Eliminar producto'}</button></div></div></Modal>;
}

function CancelOrderModal({ store, order, close, onRefresh, toast }) {
  const [reason, setReason] = useState(''); const [error, setError] = useState(''); const [saving, setSaving] = useState(false);
  const cancel = async event => { event.preventDefault(); if (!reason.trim()) { setError('Escribe el motivo de la cancelación.'); return; } try { setSaving(true); await api.updateOrder(order.id, { cancellation:{ reason:reason.trim() } }); await onRefresh(); close(); toast(order.paid ? 'Pedido cancelado y reembolso registrado.' : 'Pedido cancelado.', 'error'); } catch (exception) { setError(exception.message); } finally { setSaving(false); } };
  return <Modal onClose={close} title="Cancelar pedido"><form className="cancel-modal" onSubmit={cancel}><span className="eyebrow">ACCIÓN DE CONTROL</span><h2>Cancelar pedido #{String(order.number).padStart(3, '0')}</h2><p>{order.paid ? 'El pedido se marcará como cancelado y el importe quedará registrado para el corte.' : 'Esta acción libera la orden y detiene su seguimiento en cocina.'}</p>{order.paid && <div className="cancel-summary"><span>Importe a reembolsar</span><strong>{money(store, order.payment?.total || subtotal(order))}</strong></div>}<label className="field-label">Motivo de la cancelación<textarea autoFocus value={reason} onChange={event => { setReason(event.target.value); setError(''); }} placeholder="Describe brevemente el motivo" maxLength="240" /></label>{error && <div className="auth-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-secondary" onClick={close}>Volver</button><button className="button button-danger" disabled={saving}>{saving ? 'Cancelando…' : 'Confirmar cancelación'}</button></div></form></Modal>;
}

function PizzaModal({ store, product, close, addItem }) {
  const options = product.pizzaOptions || store.catalog.filter(item => item.kind === 'pizza'); const first = options.find(item => /pepperoni/i.test(item.name)) || options[0];
  const sizeDefinitions = configuredPizzaSizes(store.settings).filter(size => size.active !== false); const initialSize = sizeDefinitions.find(size => size.id === 'grande') || sizeDefinitions[0];
  const [config, setConfig] = useState({ options, size:initialSize?.id, mode:'completa', left:first?.id, right:first?.id, activeHalf:'left', cheeseRim:false, note:'' });
  const pizza = id => options.find(item => item.id === id) || first; const left = pizza(config.left), right = pizza(config.right); const base = config.mode === 'mitades' ? (priceForProduct(left,config.size)+priceForProduct(right,config.size))/2 : priceForProduct(left,config.size); const rim = store.catalog.find(item => item.kind === 'supplement'); const total = base + (config.cheeseRim ? priceForProduct(rim,config.size) : 0);
  const grouped = productCategories.find(category => category.id === 'pizzas').subcategories.flatMap(subcategory => [{label:subcategory,group:true},...options.filter(item=>productSubcategory(item)===subcategory).map(item=>({value:item.id,label:item.name}))]);
  const add = () => { const flavors=config.mode==='mitades'?`${left.name} / ${right.name}`:left.name; addItem({name:'Pizza',productId:left.id,category:left.category,parentCategory:productParentCategory(left),subcategory:productSubcategory(left),station:'Pizzas',unitPrice:total,details:`${sizeDefinitions.find(size=>size.id===config.size)?.name || config.size} · ${flavors}${config.cheeseRim?' · Orilla de queso':''}`,note:config.note,quantity:1,configuration:{type:'pizza',size:config.size,mode:config.mode,leftProductId:left.id,rightProductId:right.id,cheeseRim:config.cheeseRim}}); close(); };
  return <Modal onClose={close} title="Configurar pizza"><div className="pizza-modal-header"><span className="eyebrow">ARMADA A TU GUSTO</span><h2>Configura tu pizza</h2><p>Elige tamaño, sabor y orilla.</p></div><div className="pizza-builder"><div className="pizza-visual-column"><div className="pizza-visual-wrap"><PizzaScene config={config} /></div>{config.mode==='mitades'&&<div className="pizza-half-legend"><span className="half-legend-chip blue"><i/><strong>{left.name}</strong></span><span className="half-legend-chip red"><i/><strong>{right.name}</strong></span></div>}<div className="pizza-size-chips">{sizeDefinitions.map(size=><button className={`size-chip ${config.size===size.id?'selected':''}`} key={size.id} onClick={()=>setConfig({...config,size:size.id})}><strong>{size.name}</strong><small>{size.detail}</small><small>{money(store,config.mode==='mitades'?(priceForProduct(left,size.id)+priceForProduct(right,size.id))/2:priceForProduct(left,size.id))}</small></button>)}</div></div><div className="pizza-config-column"><div className="segmented-control"><button className={config.mode==='completa'?'selected':''} onClick={()=>setConfig({...config,mode:'completa',right:config.left})}>Un sabor completo</button><button className={config.mode==='mitades'?'selected':''} onClick={()=>setConfig({...config,mode:'mitades'})}>Mitad y mitad</button></div>{config.mode==='completa'?<label className="field-label">Sabor<Combo value={config.left} onChange={left=>setConfig({...config,left,right:left})} options={grouped}/></label>:<div className="half-fields"><section className={`half-choice blue-field ${config.activeHalf==='left'?'is-active':''}`}><button className="half-side-button" onClick={()=>setConfig({...config,activeHalf:'left'})}><span className="half-side-mark">1</span><strong>Mitad 1</strong></button><Combo value={config.left} onChange={left=>setConfig({...config,left,activeHalf:'left'})} options={grouped}/></section><section className={`half-choice red-field ${config.activeHalf==='right'?'is-active':''}`}><button className="half-side-button" onClick={()=>setConfig({...config,activeHalf:'right'})}><span className="half-side-mark red">2</span><strong>Mitad 2</strong></button><Combo value={config.right} onChange={right=>setConfig({...config,right,activeHalf:'right'})} options={grouped}/></section></div>}<button className={`rim-option ${config.cheeseRim?'is-selected':''}`} onClick={()=>setConfig({...config,cheeseRim:!config.cheeseRim})}><span className="rim-icon">◉</span><span><strong>Orilla rellena de queso</strong><small>{rim ? money(store,priceForProduct(rim,config.size)) : 'No disponible'}</small></span><span className="check-box">{config.cheeseRim?'✓':''}</span></button><label className="field-label">Nota<textarea value={config.note} onChange={event=>setConfig({...config,note:event.target.value})}/></label><div className="pizza-price-line"><span>Precio de esta pizza</span><strong>{money(store,total)}</strong></div><button className="button button-primary button-full" onClick={add}>Agregar pizza ＋</button></div></div></Modal>;
}

function DishModal({ store, product: base, type, close, addItem }) {
  const isBeverage = type === 'beverage';
  const list = isBeverage ? [...new Map(base.beverageGroups.flatMap(group => group.options.map(option => [option.product.id, option.product]))).values()] : base.kind === 'family' ? base.familyOptions.map(option => option.product) : [base];
  const [productId, setProductId] = useState(list[0]?.id); const product = list.find(item => item.id === productId) || list[0];
  const [variant, setVariant] = useState(product?.variants?.[0]?.label || ''); const [quantity, setQuantity] = useState(1); const [note, setNote] = useState(''); const [choices, setChoices] = useState({}); const [ingredients, setIngredients] = useState({}); const [flavorMode,setFlavorMode]=useState('completa'); const [secondFlavor,setSecondFlavor]=useState('');
  const isBurger = product?.category === 'hamburguesas';
  const isWings = productParentCategory(product) === 'alitas_boneless';
  const flavorGroup = isWings ? product?.choiceGroups?.find(group => group.label === 'Sabor') : null;
  const wingFlavors = flavorGroup?.options || [];
  const standardIngredients = ['Queso', 'Lechuga', 'Jitomate', 'Cebolla morada'];
  const ingredientOptions = isBurger ? (product.ingredientOptions || standardIngredients) : [];
  const baseIngredients = ingredientOptions.filter(ingredient => standardIngredients.includes(ingredient));
  const specialIngredients = ingredientOptions.filter(ingredient => !standardIngredients.includes(ingredient));
  useEffect(() => {
    setVariant(product?.variants?.[0]?.label || '');
    setChoices(Object.fromEntries((product?.choiceGroups || []).filter(group => !(product?.category === 'hamburguesas' && group.label === 'Queso')).map(group => [group.label, group.options[0] || ''])));
    setFlavorMode('completa');
    setSecondFlavor(product?.choiceGroups?.find(group => group.label === 'Sabor')?.options?.[1] || product?.choiceGroups?.find(group => group.label === 'Sabor')?.options?.[0] || '');
    const nextIngredients = product?.category === 'hamburguesas' ? (product.ingredientOptions || standardIngredients) : [];
    setIngredients(Object.fromEntries(nextIngredients.map(ingredient => [ingredient, true])));
  }, [productId]);
  const price = priceForProduct(product, '', variant); const products = list.map(item => ({value:item.id,label:item.name}));
  const toggleIngredient = ingredient => setIngredients(current => ({...current,[ingredient]:current[ingredient] === false}));
  const ingredientGroup = (title, options) => options.length > 0 && <section className="burger-ingredient-group"><strong>{title}</strong><div className="ingredient-grid">{options.map(ingredient => { const selected = ingredients[ingredient] !== false; return <label className={`ingredient-toggle ${selected ? 'is-selected' : ''}`} key={ingredient}><input type="checkbox" checked={selected} onChange={() => toggleIngredient(ingredient)} /><span className="check-box">{selected ? '✓' : ''}</span><span>{ingredient}</span></label>; })}</div></section>;
  const add = () => {
    const resolvedChoices = isWings ? {...choices,Sabor:flavorMode==='mitades'?`${choices.Sabor} / ${secondFlavor}`:choices.Sabor} : choices;
    const choiceText = Object.values(resolvedChoices).filter(Boolean);
    const ingredientDetails = isBurger
      ? ingredientOptions.filter(ingredient => ingredients[ingredient] === false).map(ingredient => `Sin ${ingredient.toLocaleLowerCase('es-MX')}`)
      : [];
    addItem({name:isBeverage ? 'Bebida' : base.kind === 'family' ? base.name : product.name,productId:product.id,category:product.category,parentCategory:productParentCategory(product),subcategory:productSubcategory(product),station:stationFor(product),unitPrice:price,details:[product.name,...choiceText,...ingredientDetails,variant].filter(Boolean).join(' · '),note,quantity,configuration:{type:'dish',choices,variant,excludedIngredients:ingredientOptions.filter(ingredient => ingredients[ingredient] === false),...(isWings?{flavorMode,leftFlavor:choices.Sabor,rightFlavor:flavorMode==='mitades'?secondFlavor:choices.Sabor}:{})}}); close();
  };
  const parentLabel = productCategories.find(category => category.id === productParentCategory(product))?.label || productParentCategory(product);
  return <Modal onClose={close} title={`Configurar ${base.name}`}><div className="dish-modal-header"><span className="product-art"><img className="dish-icon" src={`/assets/icons/${dishIcon(product)}.svg`} alt="" /></span><div><span className="eyebrow">{parentLabel} · {productSubcategory(product)}</span><h2>Configura {base.name}</h2><p>{isWings?'Elige alitas o boneless, con un sabor o mitad de dos sabores.':product.description || 'Preparado al momento.'}</p></div></div><div className="dish-modal-body"><label className="field-label">{isBeverage ? 'Bebida' : base.kind === 'family' ? base.familyChoiceGroup?.label : 'Selección'}<Combo value={productId} onChange={setProductId} options={products}/></label>{(product.choiceGroups || []).filter(group => !(isBurger && group.label === 'Queso') && !(isWings && group.label === 'Sabor')).map(group => <label className="field-label" key={group.label}>{group.label}<Combo value={choices[group.label] || ''} onChange={value => setChoices({...choices,[group.label]:value})} options={group.options.map(option => ({value:option,label:option}))} /></label>)}{isWings&&<section className="wing-flavor-builder"><span className="field-label">Sabores</span><div className="segmented-control"><button type="button" className={flavorMode==='completa'?'selected':''} onClick={()=>setFlavorMode('completa')}>Un sabor</button><button type="button" className={flavorMode==='mitades'?'selected':''} onClick={()=>setFlavorMode('mitades')}>Mitad y mitad</button></div>{flavorMode==='completa'?<label className="field-label">Sabor<Combo value={choices.Sabor||wingFlavors[0]} onChange={value=>setChoices({...choices,Sabor:value})} options={wingFlavors.map(value=>({value,label:value}))}/></label>:<div className="half-fields"><section className="half-choice blue-field is-active"><div className="half-side-button"><span className="half-side-mark">1</span><strong>Mitad 1</strong></div><Combo value={choices.Sabor||wingFlavors[0]} onChange={value=>setChoices({...choices,Sabor:value})} options={wingFlavors.map(value=>({value,label:value}))}/></section><section className="half-choice red-field"><div className="half-side-button"><span className="half-side-mark red">2</span><strong>Mitad 2</strong></div><Combo value={secondFlavor||wingFlavors[0]} onChange={setSecondFlavor} options={wingFlavors.map(value=>({value,label:value}))}/></section></div>}</section>}{isBurger && <fieldset className="field-label ingredient-field"><legend>Ingredientes incluidos</legend>{ingredientGroup('Ingredientes base',baseIngredients)}{ingredientGroup('Ingredientes de esta hamburguesa',specialIngredients)}<small className="field-help">Desmarca cualquier ingrediente que el cliente no quiera. La comanda indicará claramente los ingredientes retirados.</small></fieldset>}{product.variants?.length > 0 && <label className="field-label">Presentación<Combo value={variant} onChange={setVariant} options={product.variants.map(item => ({value:item.label,label:`${item.label} · ${money(store,item.price)}`}))} /></label>}<label className="field-label">Nota para cocina<textarea value={note} onChange={event => setNote(event.target.value)} /></label><div className="dish-quantity-price"><div><span className="eyebrow">CANTIDAD</span><div className="stepper"><button onClick={() => setQuantity(Math.max(1,quantity-1))}>−</button><span>{quantity}</span><button onClick={() => setQuantity(quantity+1)}>＋</button></div></div><div className="dish-price"><span>Precio</span><strong>{money(store,price*quantity)}</strong></div></div><button className="button button-primary button-full" onClick={add}>Agregar al pedido ＋</button></div></Modal>;
}

function PaymentModal({ store, order, close, onRefresh, toast }) {
  const deliverySettlement=order.type==='domicilio'; const [method,setMethod]=useState('Efectivo'); const [received,setReceived]=useState(String(subtotal(order))); const [tipType,setTipType]=useState('ninguna'); const [tipValue,setTipValue]=useState(''); const [error,setError]=useState(''); const sub=subtotal(order); const fee=method==='Tarjeta'?Math.round(sub*.04):0; const tip=method==='Efectivo'||tipType==='ninguna'?0:tipType==='porcentaje'?Math.round(sub*Number(tipValue||0)/100):Number(tipValue||0); const total=sub+fee+tip;
  const pay=async()=>{ try { setError(''); const updated=await api.updateOrder(order.id,{payment:{method,received:method==='Efectivo'?Number(received):total,tipType,tipValue:Number(tipValue||0)}}); if (order.type !== 'domicilio') printTicket(store,updated,null,true); await onRefresh(); close(); toast(order.type === 'domicilio' ? 'Dinero recibido y pedido finalizado.' : 'Pedido cobrado y cerrado.'); } catch(exception) { setError(exception.message); } };
  return <Modal onClose={close} title={deliverySettlement?'Liquidar entrega':'Registrar pago'}><div className="editor-modal-header"><span className="eyebrow">{deliverySettlement?'LIQUIDACIÓN DEL REPARTIDOR':'COBRO'} · PEDIDO #{order.number}</span><h2>{deliverySettlement?'Registra el dinero que regresó a caja':'Revisa el total antes de cobrar'}</h2></div><div className="payment-modal-body"><label className="field-label">Forma de pago<Combo value={method} onChange={setMethod} options={['Efectivo','Tarjeta','Transferencia'].map(value=>({value,label:value}))}/></label>{method!=='Efectivo'&&<><div className="tip-type-cards"><button className={tipType==='ninguna'?'selected':''} onClick={()=>setTipType('ninguna')}>Sin propina</button><button className={tipType==='porcentaje'?'selected':''} onClick={()=>setTipType('porcentaje')}>Porcentaje</button><button className={tipType==='cantidad'?'selected':''} onClick={()=>setTipType('cantidad')}>Pesos</button></div>{tipType!=='ninguna'&&<label className="field-label">Propina<input type="number" min="0" value={tipValue} onChange={event=>setTipValue(event.target.value)} /></label>}</>}{method==='Efectivo'&&<label className="field-label">{deliverySettlement?'Efectivo entregado por el repartidor':'Efectivo recibido'}<input type="number" min="0" value={received} onChange={event=>setReceived(event.target.value)} /></label>}{error&&<div className="auth-error" role="alert">{error}</div>}<div className="payment-line-items"><div><span>Subtotal</span><strong>{money(store,sub)}</strong></div>{fee>0&&<div><span>Comisión terminal (4%)</span><strong>{money(store,fee)}</strong></div>}{tip>0&&<div><span>Propina</span><strong>{money(store,tip)}</strong></div>}</div><div className="payment-due"><span>{deliverySettlement?'Total que debe ingresar a caja':'Total a cobrar'}</span><strong>{money(store,total)}</strong></div><button className="button button-primary button-full" onClick={pay}>{deliverySettlement?'Confirmar dinero y finalizar pedido':'Confirmar pago y cerrar pedido'}</button></div></Modal>;
}
